69	+++ b/seed-b-backend.Api/Services/RatingService.cs
70	@@ -0,0 +1,61 @@
71	+using Microsoft.EntityFrameworkCore;
72	+using seed_b_backend.Api.Data;
73	+using seed_b_backend.Api.Data.Entities;
74	+using seed_b_backend.Api.Dtos;
75	+
76	+namespace seed_b_backend.Api.Services;
77	+
78	+public class RatingService(AppDbContext db)
79	+{
80	+    public async Task<RatingSummaryDto?> UpsertRatingAsync(string productId, string authorName, int value)
81	+    {
82	+        var productExists = await db.Products.AnyAsync(p => p.Id == productId);
83	+        if (!productExists)
84	+        {
85	+            return null; // Controller mappt auf 404, analog ProductService.GetProductDetailAsync
86	+        }
87	+
88	+        var rowsAffected = await db.Ratings
89	+            .Where(r => r.ProductId == productId && r.AuthorName == authorName)
90	+            .ExecuteUpdateAsync(s => s.SetProperty(r => r.Value, value));
91	+
92	+        if (rowsAffected == 0)
93	+        {
94	+            var newRating = new Rating { Id = Guid.NewGuid(), ProductId = productId, AuthorName = authorName, Value = value };
95	+            db.Ratings.Add(newRating);
96	+            try
97	+            {
98	+                await db.SaveChangesAsync();
99	+            }
100	+            catch (DbUpdateException)
101	+            {
102	+                // Verloren gegangenes Wettrennen: ein konkurrierender Request hat dieselbe
103	+                // (ProductId, AuthorName)-Zeile zwischen unserem ExecuteUpdateAsync (0 Zeilen)
104	+                // und diesem SaveChangesAsync bereits eingefügt — der eindeutige Index (AD-8,
105	+                // Migration AddRating aus Story 2.1) hat den Insert-Konflikt abgefangen.
106	+                // NFR-3 verlangt: kein Konfliktfehler nach außen, sondern Update auf die jetzt
107	+                // existierende Zeile (Last-Write-Wins).
108	+                db.Entry(newRating).State = EntityState.Detached;
109	+                await db.Ratings
110	+                    .Where(r => r.ProductId == productId && r.AuthorName == authorName)
111	+                    .ExecuteUpdateAsync(s => s.SetProperty(r => r.Value, value));
112	+            }
113	+        }
114	+
115	+        return await ComputeSummaryAsync(productId);
116	+    }
117	+
118	+    private async Task<RatingSummaryDto> ComputeSummaryAsync(string productId)
119	+    {
120	+        var values = await db.Ratings
121	+            .Where(r => r.ProductId == productId)
122	+            .Select(r => r.Value)
123	+            .ToListAsync();
124	+
125	+        double? average = values.Count == 0
126	+            ? null
127	+            : Math.Round(values.Average(), 1, MidpointRounding.AwayFromZero);
128	+
129	+        return new RatingSummaryDto(average, values.Count);
130	+    }
131	+}
