148	+    // ExecuteUpdateAsync (the race-safe upsert, AC #1/#3/#4/AD-8) is not supported by
149	+    // EF Core's InMemory provider, unlike other tests in this project — SQLite's ":memory:" mode is
150	+    // used instead because it is a real relational engine that does translate ExecuteUpdate to SQL.
151	+    private sealed class TestDb : IAsyncDisposable
152	+    {
153	+        public AppDbContext Db { get; }
154	+        private readonly SqliteConnection _connection;
155	+
