164	+            var connection = new SqliteConnection("DataSource=:memory:");
165	+            connection.Open();
166	+            var options = new DbContextOptionsBuilder<AppDbContext>().UseSqlite(connection).Options;
167	+            var db = new AppDbContext(options);
168	+            db.Database.EnsureCreated();
169	+            return new TestDb(db, connection);
170	+        }
171	+
172	+        public async ValueTask DisposeAsync()
173	+        {
174	+            await Db.DisposeAsync();
175	+            await _connection.DisposeAsync();
176	+        }
