179	+    private static async Task SeedProductAsync(AppDbContext db, string productId = "P1")
180	+    {
181	+        db.Categories.Add(new Category { Id = "C1", Name = "Kategorie 1" });
182	+        db.Subcategories.Add(new Subcategory { Id = "S1", Name = "Unterkategorie 1", CategoryId = "C1" });
183	+        db.Products.Add(new Product { Id = productId, Name = "Produkt 1", Description = "d", SubcategoryId = "S1", Attributes = "{}" });
184	+        await db.SaveChangesAsync();
185	+    }
186	+
187	+    [Fact]
188	+    public async Task UpsertRatingAsync_ProductWithoutRatings_ReturnsAverage5AndCount1AndPersistsRating()
189	+    {
190	+        await using var testDb = TestDb.Create();
191	+        var db = testDb.Db;
192	+        await SeedProductAsync(db);
193	+        var service = new RatingService(db);
194	+
195	+        var result = await service.UpsertRatingAsync("P1", "Jonas", 5);
196	+
197	+        Assert.NotNull(result);
198	+        Assert.Equal(5.0, result!.AverageRating);
199	+        Assert.Equal(1, result.RatingCount);
200	+        var rating = await db.Ratings.SingleAsync(r => r.ProductId == "P1" && r.AuthorName == "Jonas");
201	+        Assert.Equal(5, rating.Value);
202	+    }
203	+
204	+    [Fact]
205	+    public async Task UpsertRatingAsync_ExistingRatingSameAuthor_ReplacesValueWithoutCreatingSecondRow()
206	+    {
207	+        await using var testDb = TestDb.Create();
208	+        var db = testDb.Db;
209	+        await SeedProductAsync(db);
210	+        var service = new RatingService(db);
211	+        await service.UpsertRatingAsync("P1", "Jonas", 3);
212	+
213	+        var result = await service.UpsertRatingAsync("P1", "Jonas", 5);
214	+
215	+        Assert.NotNull(result);
216	+        Assert.Equal(1, await db.Ratings.CountAsync(r => r.ProductId == "P1" && r.AuthorName == "Jonas"));
217	+        var rating = await db.Ratings.AsNoTracking().SingleAsync(r => r.ProductId == "P1" && r.AuthorName == "Jonas");
218	+        Assert.Equal(5, rating.Value);
219	+    }
220	+
221	+    [Fact]
222	+    public async Task UpsertRatingAsync_TwoDifferentAuthors_CreatesSeparateRowsAndAggregatesBoth()
223	+    {
224	+        await using var testDb = TestDb.Create();
225	+        var db = testDb.Db;
226	+        await SeedProductAsync(db);
227	+        var service = new RatingService(db);
228	+        await service.UpsertRatingAsync("P1", "A", 5);
229	+
230	+        var result = await service.UpsertRatingAsync("P1", "B", 3);
231	+
232	+        Assert.NotNull(result);
233	+        Assert.Equal(2, result!.RatingCount);
234	+        Assert.Equal(4.0, result.AverageRating);
235	+    }
236	+
237	+    [Fact]
238	+    public async Task UpsertRatingAsync_UnknownProductId_ReturnsNullAndPersistsNoRating()
239	+    {
240	+        await using var testDb = TestDb.Create();
241	+        var db = testDb.Db;
242	+        await SeedProductAsync(db);
243	+        var service = new RatingService(db);
244	+
245	+        var result = await service.UpsertRatingAsync("P9", "Jonas", 5);
246	+
247	+        Assert.Null(result);
248	+        Assert.Equal(0, await db.Ratings.CountAsync());
249	+    }
250	+
251	+    [Fact]
252	+    public async Task UpsertRatingAsync_ThreeRatingsValues544_ReturnsAverage43()
253	+    {
254	+        await using var testDb = TestDb.Create();
255	+        var db = testDb.Db;
256	+        await SeedProductAsync(db);
257	+        var service = new RatingService(db);
258	+        await service.UpsertRatingAsync("P1", "A", 5);
259	+        await service.UpsertRatingAsync("P1", "B", 4);
260	+
261	+        var result = await service.UpsertRatingAsync("P1", "C", 4);
262	+
263	+        Assert.NotNull(result);
264	+        Assert.Equal(4.3, result!.AverageRating);
265	+        Assert.Equal(3, result.RatingCount);
266	+    }
267	+}
