+        await SeedProductAsync(db);
+        var service = new RatingService(db);
+
+        var result = await service.UpsertRatingAsync("P1", "Jonas", 5);
+
+        Assert.NotNull(result);
+        Assert.Equal(5.0, result!.AverageRating);
