1	using Microsoft.EntityFrameworkCore;
2	using seed_b_backend.Api.Data.Entities;
3	
4	namespace seed_b_backend.Api.Data;
5	
6	public class AppDbContext(DbContextOptions<AppDbContext> options) : DbContext(options)
7	{
8	    public DbSet<Category> Categories => Set<Category>();
9	    public DbSet<Subcategory> Subcategories => Set<Subcategory>();
10	    public DbSet<Supplier> Suppliers => Set<Supplier>();
11	    public DbSet<Product> Products => Set<Product>();
12	    public DbSet<Offer> Offers => Set<Offer>();
13	    public DbSet<Rating> Ratings => Set<Rating>();
14	
15	    protected override void OnModelCreating(ModelBuilder modelBuilder)
16	    {
17	        modelBuilder.Entity<Category>()
18	            .HasMany(c => c.Subcategories)
19	            .WithOne(s => s.Category)
20	            .HasForeignKey(s => s.CategoryId);
21	
22	        modelBuilder.Entity<Subcategory>()
23	            .HasMany(s => s.Products)
24	            .WithOne(p => p.Subcategory)
25	            .HasForeignKey(p => p.SubcategoryId);
26	
27	        modelBuilder.Entity<Product>()
28	            .Property(p => p.ViewCount)
29	            .HasDefaultValue(0);
30	
31	        modelBuilder.Entity<Offer>(o =>
32	        {
33	            o.HasKey(x => new { x.ProductId, x.SupplierId });
34	            o.Property(x => x.Price).HasColumnType("decimal(18,2)");
35	
36	            o.HasOne(x => x.Product)
37	                .WithMany(p => p.Offers)
38	                .HasForeignKey(x => x.ProductId);
39	
40	            o.HasOne(x => x.Supplier)
41	                .WithMany(s => s.Offers)
42	                .HasForeignKey(x => x.SupplierId);
43	        });
44	
45	        modelBuilder.Entity<Rating>(r =>
46	        {
47	            r.HasIndex(x => new { x.ProductId, x.AuthorName }).IsUnique();
48	            r.HasOne(x => x.Product)
49	                .WithMany()
50	                .HasForeignKey(x => x.ProductId);
51	        });
52	    }
53	}
